import assert from "node:assert/strict";
import { mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { dirname, join, resolve } from "node:path";
import { pathToFileURL } from "node:url";
import * as ts from "typescript";
import { createHash } from "node:crypto";
import { gzipSync } from "node:zlib";

const root = process.cwd();
const out = join(root, "tmp/optimization-implementation-20261015/tooling");
const revision = "b2926b14880da7546f39aba7c0e07424f65f3977";
const baselinePaths = [
  "scripts/docs/package-documents.ts",
  "scripts/docs/package-api/jsdoc-render.ts",
  "scripts/docs/package-api/jsdoc-target-discovery.ts",
  "scripts/docs/package-api/markdown-example-fences.ts",
  "scripts/package/artifact/esm-module-specifiers.ts",
  "scripts/package/artifact/packed-tar-audit.ts",
  "scripts/validation/repository-material/links.ts",
  "scripts/validation/repository-material/machine-artifacts/canonical.ts",
  ...["simulate", "simulation-clock", "simulation-control", "simulation-evidence", "simulation-observations", "simulation-types"].map(name => `scripts/project/admission-workbench/${name}.ts`)
];
const baselineFiles = new Map(baselinePaths.map(path => [resolve(root, path), join(out, "baseline", path)]));
// Snapshots are read from the frozen initial HEAD, never from another agent's working tree.
// Rewrite only real import/export module literals and literal import.meta.resolve calls.
for (const path of baselinePaths) {
  const response = Bun.spawnSync(["git", "show", `${revision}:${path}`], { cwd: root });
  assert.equal(response.exitCode, 0);
  let source = response.stdout.toString();
  const sourceFile = ts.createSourceFile(path, source, ts.ScriptTarget.Latest, true, ts.ScriptKind.TS);
  const replacements = [];
  const visit = node => {
    if (ts.isStringLiteral(node)) {
      const parent = node.parent;
      const isModule = ((ts.isImportDeclaration(parent) || ts.isExportDeclaration(parent)) && parent.moduleSpecifier === node)
        || (ts.isCallExpression(parent) && parent.arguments[0] === node && parent.expression.getText(sourceFile) === "import.meta.resolve");
      if (isModule && (node.text.startsWith(".") || node.text === "@zxyycom/vibe-check")) {
        const target = node.text === "@zxyycom/vibe-check" ? join(root, "scripts/project/node_modules/@zxyycom/vibe-check/index.mjs") : resolve(dirname(join(root, path)), node.text);
        replacements.push({ start: node.getStart(sourceFile), end: node.end, text: JSON.stringify(baselineFiles.get(target) ?? target) });
      }
    }
    ts.forEachChild(node, visit);
  };
  visit(sourceFile);
  for (const replacement of replacements.sort((a, b) => b.start - a.start)) source = source.slice(0, replacement.start) + replacement.text + source.slice(replacement.end);
  const destination = baselineFiles.get(join(root, path));
  mkdirSync(dirname(destination), { recursive: true });
  writeFileSync(destination, source);
}

const loadPair = async path => [await import(pathToFileURL(baselineFiles.get(join(root, path))).href), await import(pathToFileURL(join(root, path)).href)];
const outcome = callback => { try { return { value: callback() }; } catch (error) { return { error: error.message }; } };
const summary = { revision, runtime: Bun.version, timing: "not measured; operation counts and exact output comparisons only", comparisons: {}, operations: {} };

const [markdownBefore, markdownAfter] = await loadPair("scripts/docs/package-api/markdown-example-fences.ts");
let markdownComparisons = 0;
const compareMarkdown = input => {
  assert.deepEqual(outcome(() => markdownAfter.renderMarkdownExampleFences(input)), outcome(() => markdownBefore.renderMarkdownExampleFences(input)));
  markdownComparisons += 1;
};
for (let count = 1; count <= 64; count += 1) {
  const sections = Array.from({ length: count }, (_, i) => `## S${i}\n\n保留😀 ${i}\n\n~~~ts\nstale ${i}\n~~~`);
  const sourceMarkdown = `# Fixture\n\n${sections.join("\n\n")}\n`;
  const replacements = sections.map((_, i) => ({ headingPath: [`S${i}`], replacementLines: ["```ts", `next ${i}`, "```", ...(i % 3 === 0 ? ["tail"] : [])] }));
  for (const selected of [replacements, replacements.toReversed(), replacements.filter((_, i) => i % 2), [], [...replacements, replacements[0]], [{ headingPath: ["missing"], replacementLines: ["x"] }]]) {
    compareMarkdown({ documentPackagePath: "docs/fixture.md", sourceMarkdown, replacements: selected });
  }
}
for (const level of [2, 3, 4, 6]) {
  const sourceMarkdown = `# Fixture\n\n## Parent\n\n${"#".repeat(level)} Child\n\n\`\`\`ts\nold\n\`\`\`\n\n## Following\nprose\n`;
  for (const replacements of [
    [{ headingPath: ["Parent"], replacementLines: ["```ts", "parent", "extra", "```"] }, { headingPath: level === 2 ? ["Child"] : ["Parent", "Child"], replacementLines: ["```ts", "child", "```"] }],
    [{ headingPath: ["Parent"], replacementLines: [] }]
  ]) compareMarkdown({ documentPackagePath: "docs/fixture.md", sourceMarkdown, replacements });
}
summary.comparisons.markdown = markdownComparisons;

const [jsdocBefore, jsdocAfter] = await loadPair("scripts/docs/package-api/jsdoc-render.ts");
const jsdocRoot = join(out, "workloads/jsdoc");
mkdirSync(join(jsdocRoot, "src"), { recursive: true });
let jsdocComparisons = 0;
for (const count of [1, 2, 8, 64]) {
  const declarations = Array.from({ length: count }, (_, i) => `/**\n * Prose ${i} 😀.\n */\nexport function Target${i}() { return ${i}; }\n`);
  const projections = declarations.map((_, i) => ({ id: `example-${i}`, title: `Example ${i}`, targets: [{ kind: "jsdoc", sourcePath: "src/targets.ts", declarationName: `Target${i}` }] }));
  const payloads = new Map(projections.map((p, i) => [p.id, { content: `const value = ${i};\n`, sourcePath: `example-${i}.ts` }]));
  for (const suffix of ["", declarations[0], "\n/** Detached */\nconst irrelevant = 1;\nexport function Missing() {}\n"]) {
    writeFileSync(join(jsdocRoot, "src/targets.ts"), `// preamble\n${declarations.join("\n")}${suffix}// suffix\n`);
    assert.deepEqual(outcome(() => jsdocAfter.renderJSDocSources(jsdocRoot, projections, payloads)), outcome(() => jsdocBefore.renderJSDocSources(jsdocRoot, projections, payloads)));
    jsdocComparisons += 1;
  }
}
for (const names of [["A", "A$"], ["A$", "A$x"], ["A", "A$x"], ["$", "_"], ["A", "AB"]]) {
  const projections = names.map((declarationName, i) => ({ id: `example-${i}`, title: `Example ${i}`, targets: [{ kind: "jsdoc", sourcePath: "src/targets.ts", declarationName }] }));
  const payloads = new Map(projections.map(p => [p.id, { content: "void 0;\n", sourcePath: "example.ts" }]));
  writeFileSync(join(jsdocRoot, "src/targets.ts"), "/**\n * Prose.\n */\nexport function A$x() {}\n/**\n * Other prose.\n */\nexport function AB() {}\n");
  assert.deepEqual(outcome(() => jsdocAfter.renderJSDocSources(jsdocRoot, projections, payloads)), outcome(() => jsdocBefore.renderJSDocSources(jsdocRoot, projections, payloads)));
  jsdocComparisons += 1;
}
summary.comparisons.jsdoc = jsdocComparisons;

const [registryBefore, registryAfter] = await loadPair("scripts/docs/package-documents.ts");
const registryRoot = join(out, "workloads/registry");
mkdirSync(join(registryRoot, "docs"), { recursive: true });
const registry = { markdownDocuments: [{ id: "readme", sourcePath: "README.md", packagePath: "README.md" }], checkGuides: [{ checkId: "fixture", exportName: "fixture", sourcePath: "docs/check.md", packagePath: "docs/check.md" }], machineMaterials: Array.from({ length: 512 }, (_, i) => ({ sourcePath: "docs/input.json", packagePath: `docs/group-${i}/item.json` })) };
let registryComparisons = 0;
for (const tail of [[], [{ packagePath: "docs/group-0" }], [{ packagePath: "docs/group-511/item.json/child" }], [{ packagePath: "docs/group-512" }, { packagePath: "docs/group-512/child" }], [{ packagePath: "docs/group-512/child" }, { packagePath: "docs/group-512" }], [{ packagePath: "docs/group-0-prefix/sibling" }]]) {
  writeFileSync(join(registryRoot, "docs/package-documents.json"), JSON.stringify({ ...registry, machineMaterials: [...registry.machineMaterials, ...tail.map(x => ({ sourcePath: "docs/input.json", ...x }))] }));
  assert.deepEqual(outcome(() => registryAfter.loadPackageDocuments(registryRoot)), outcome(() => registryBefore.loadPackageDocuments(registryRoot)));
  registryComparisons += 1;
}
summary.comparisons.registry = registryComparisons;

const [canonicalBefore, canonicalAfter] = await loadPair("scripts/validation/repository-material/machine-artifacts/canonical.ts");
let canonicalComparisons = 0;
for (let depth = 0; depth < 256; depth += 1) {
  let value = { z: -0, a: ["😀", true, null, "quote\"\\\n"] };
  for (let level = 0; level < depth; level += 1) value = { z: [level], a: value };
  assert.equal(canonicalAfter.canonicalJsonText(value), canonicalBefore.canonicalJsonText(value));
  canonicalComparisons += 1;
}
summary.comparisons.canonical = canonicalComparisons;
const observedCanonicalObject = mode => {
  const trace = [];
  const observe = (target, label) => new Proxy(target, {
    getPrototypeOf(object) { trace.push(`${label}:prototype`); return Reflect.getPrototypeOf(object); },
    ownKeys(object) { trace.push(`${label}:keys`); return Reflect.ownKeys(object); },
    getOwnPropertyDescriptor(object, key) { trace.push(`${label}:descriptor:${String(key)}`); return Reflect.getOwnPropertyDescriptor(object, key); }
  });
  const target = { b: 2, a: observe({ z: 1, a: -0 }, "child") };
  if (mode === "accessor") Object.defineProperty(target, "b", { enumerable: true, get() { trace.push("getter-called"); return 2; } });
  if (mode === "hidden") Object.defineProperty(target, "hidden", { value: 1 });
  if (mode === "symbol") target[Symbol("hidden")] = 1;
  if (mode === "prototype") Object.setPrototypeOf(target, { custom: true });
  return { value: observe(target, "root"), trace };
};
for (const mode of ["valid", "accessor", "hidden", "symbol", "prototype"]) {
  const before = observedCanonicalObject(mode);
  const after = observedCanonicalObject(mode);
  assert.equal(canonicalAfter.canonicalJsonText(after.value), canonicalBefore.canonicalJsonText(before.value));
  assert.deepEqual(after.trace, before.trace);
}
summary.comparisons.canonicalAccessOrder = 5;

const [esmBefore, esmAfter] = await loadPair("scripts/package/artifact/esm-module-specifiers.ts");
for (const count of [0, 1, 2, 64, 512]) {
  const source = ["// preamble", ...Array.from({ length: count }, (_, i) => `import { value as local${i} } from './m-${i}.js';`), "const ordinary = './path.js';", ""].join("\n");
  assert.equal(esmAfter.rewriteRelativeEsmModuleExtensions({ fileName: "fixture.mjs", source }), esmBefore.rewriteRelativeEsmModuleExtensions({ fileName: "fixture.mjs", source }));
}
summary.comparisons.esm = 5;

const [linksBefore, linksAfter] = await loadPair("scripts/validation/repository-material/links.ts");
const linksRoot = join(out, "workloads/links");
mkdirSync(join(linksRoot, "docs"), { recursive: true });
for (const count of [1, 64, 2048]) {
  const source = Array.from({ length: count }, (_, i) => `${"😀".repeat(i % 3)}[external](https://example.invalid) [missing](missing-${i % 5}.md)`).join("\n");
  writeFileSync(join(linksRoot, "docs/source.md"), `${source}\n`);
  const options = { repositoryRoot: linksRoot, markdownLinkRoots: ["docs/source.md"] };
  assert.deepEqual(linksAfter.collectMarkdownLinkDiagnostics(options), linksBefore.collectMarkdownLinkDiagnostics(options));
}
summary.comparisons.links = 3;

const [tarBefore, tarAfter] = await loadPair("scripts/package/artifact/packed-tar-audit.ts");
const tarPath = join(out, "workloads/materials.tar.gz");
const packEntries = entries => {
  const chunks = [];
  for (const entry of entries) {
    const content = Buffer.from(entry.content);
    const header = Buffer.alloc(512);
    header.write(entry.path);
    header.write(content.length.toString(8).padStart(11, "0"), 124);
    header[156] = entry.type ?? 48;
    chunks.push(header, content, Buffer.alloc((512 - content.length % 512) % 512));
  }
  return gzipSync(Buffer.concat([...chunks, Buffer.alloc(1024)]));
};
const document = { path: "package/docs/document.md", content: "# Exact\n" };
const machine = { path: "package/docs/data.json", content: "{}\n" };
let tarComparisons = 0;
for (const entries of [[document, machine], [machine], [document], [{ ...document, content: "changed" }, machine], [document, { ...document, content: "duplicate" }, machine], [document, machine, { path: "package/unsupported", content: "", type: 50 }]]) {
  const archive = packEntries(entries);
  writeFileSync(tarPath, archive);
  const input = { artifactPath: tarPath, candidateVersion: "0.0.0-candidate", repositoryRoot: root, expectedFiles: [], expectedDocuments: [{ packagePath: "docs/document.md", content: document.content }], expectedMachineMaterials: [{ packagePath: "docs/data.json", content: Buffer.from(machine.content) }], expectedJSDocExamplePayloads: [], expectedReadme: "", expectedAttributionNotice: Buffer.alloc(0), expectedSha256: createHash("sha256").update(archive).digest("hex") };
  assert.deepEqual(outcome(() => tarAfter.auditCandidateArtifact(input)), outcome(() => tarBefore.auditCandidateArtifact(input)));
  tarComparisons += 1;
}
summary.comparisons.tarMaterialRejectionPrecedence = tarComparisons;

const [simulationBefore, simulationAfter] = await loadPair("scripts/project/admission-workbench/simulate.ts");
const { FIXTURES } = await import(pathToFileURL(join(root, "scripts/project/admission-workbench/fixture-registry.ts")).href);
let simulations = 0;
for (const fixture of Object.values(FIXTURES)) {
  for (const seed of [0, 7, 19]) {
    assert.deepEqual(simulationAfter.simulate(fixture, undefined, seed), simulationBefore.simulate(fixture, undefined, seed));
    simulations += 1;
  }
}
summary.comparisons.simulation = simulations;

// Explicit operation models, not runtime/GC/allocation or end-to-end timing claims.
const n = 4096;
summary.operations.registryFixedDepth = { targets: n, beforePathComparisons: n * (n - 1) / 2, afterSetMembershipUpperBound: 5 * n, note: "fixed docs/group/file depth; string hashing/prefix bytes remain" };
summary.operations.lanes = { files: n, beforeEqualityChecks: n * (n + 1), afterSetMembershipChecks: 2 * n, note: "two successful includes scans versus two has scans; set construction separate" };
summary.operations.observationHistory = { actions: n, beforeCopiedReferences: n * (n - 1) / 2, beforeWaitContributionsReduced: n * (n - 1) / 2, afterHistoryCopies: 0, afterContributionAdds: n, note: "full final evidence and per-action context/state remain" };
const source = Array.from({ length: 2048 }, (_, i) => `${"😀".repeat(i % 3)}[external](https://example.invalid) [missing](missing-${i % 5}.md)`).join("\n") + "\n";
const offsets = [...source.matchAll(/\[[^\]]+\]\(([^)]+)\)/g)].filter(match => !match[1].startsWith("http")).map(match => match.index);
summary.operations.missingLinkLocation = { links: offsets.length, sourceUtf16Units: source.length, beforePrefixUnits: offsets.reduce((a, b) => a + b, 0), afterVisitedUtf16UpperBound: offsets.at(-1), note: "only missing locations incur scanning; code-point cursor advances once in matchAll order" };
const depth = 256;
summary.operations.canonicalDeepSingleton = { depth, serializedBytes: 2 * depth + 1, beforeSubtreeTextUnits: (depth + 1) ** 2, afterFinalTextUnits: 2 * depth + 1, note: "nested arrays around 0, chunks join once; recursive stack/key checks remain" };
summary.operations.tarMaterialLookup = { entries: 4096, materials: 512, beforePathComparisonsWorstCase: 4096 * 512, afterIndexVisits: 4096, afterLookups: 512, note: "complete decompression/digest/inventory/legal audit unchanged" };
summary.operations.topicCounts = { topics: 15, cases: 181, beforeTopicComparisons: 15 * 181, afterCountUpdates: 181, afterLookups: 15, note: "catalog parsing, validation and full-tree closure unchanged" };
const importCount = 512;
const esmSource = ["// preamble", ...Array.from({ length: importCount }, (_, i) => `import { value as local${i} } from './m-${i}.js';`), "const ordinary = './path.js';", ""].join("\n");
summary.operations.esmTextConstruction = { imports: importCount, sourceUnits: esmSource.length, beforeIntermediateTextUnits: importCount * esmSource.length + importCount * (importCount + 1) / 2, afterFinalTextUnits: esmSource.length + importCount, note: "logical strings, not actual rope allocations; quoted token replacement grows by one unit" };
summary.operations.jsdocSingleSource = { targets: 128, beforeSourceReads: 130, afterSourceReads: 1, note: "discovery + per-target reads + final reconstruction read; per-target regex search remains" };
summary.operations.backtickDelimiter = { longestRun: 128, beforeIncludesInvocations: 127, afterMatchAllInvocations: 1, note: "delimiter lengths 3 through 129; this counts searches, not engine-internal character comparisons" };
writeFileSync(join(out, "equivalence-results.json"), `${JSON.stringify(summary, null, 2)}\n`);
console.log(JSON.stringify(summary, null, 2));
